          mn: [{ k: '위·비·증·화', s: '**위**축은 줄고, **비**대는 커지고, **증**식은 늘고, **화**생은 옷을 갈아입는다', map: [['위', '위축 · 크기↓'], ['비', '비대 · 크기↑'], ['증', '증식 · 수↑'], ['화', '화생 · 종류 변화']] }],
